#!/usr/bin/env python3
"""Verify the self-signed TLS certificate used by the internal dev server."""

import datetime
import hashlib
import os
import ssl
import subprocess
import sys

CERT_PATH = os.environ.get("CERT_PATH", "/app/ssl/server.crt")
KEY_PATH = os.environ.get("KEY_PATH", "/app/ssl/server.key")
PEM_PATH = os.environ.get("PEM_PATH", "/app/ssl/server.pem")


def fail(message):
    print(f"Certificate verification failed: {message}", file=sys.stderr)
    return 1


def get_field(decoded, prefix):
    """Return the first value from a decoded certificate field like 'subject'."""
    for key, value in decoded.get(prefix, ()):
        if key == "commonName":
            return value
    return None


def key_matches_certificate(cert_path, key_path):
    """Compare the public keys of the certificate and private key via OpenSSL."""
    try:
        cert_pub = subprocess.run(
            ["openssl", "x509", "-in", cert_path, "-noout", "-pubkey"],
            check=True, capture_output=True,
        ).stdout
        key_pub = subprocess.run(
            ["openssl", "pkey", "-in", key_path, "-pubout"],
            check=True, capture_output=True,
        ).stdout
    except (OSError, subprocess.CalledProcessError) as exc:
        raise RuntimeError(f"unable to compare public keys: {exc}") from exc
    return hashlib.sha256(cert_pub).digest() == hashlib.sha256(key_pub).digest()


def main():
    # The certificate must exist and be loadable.
    if not os.path.isfile(CERT_PATH):
        return fail(f"{CERT_PATH} does not exist")
    if os.path.getsize(CERT_PATH) == 0:
        return fail(f"{CERT_PATH} is empty")

    try:
        with open(CERT_PATH, "r", encoding="utf-8") as handle:
            pem_data = handle.read()
        der_data = ssl.PEM_cert_to_DER_cert(pem_data)
        decoded = ssl._ssl._test_decode_cert(CERT_PATH)
    except (OSError, ssl.SSLError, ValueError) as exc:
        return fail(f"cannot load certificate: {exc}")

    common_name = get_field(decoded, "subject")
    if not common_name:
        return fail("certificate has no Common Name")

    try:
        expires = datetime.datetime.strptime(
            decoded["notAfter"], "%b %d %H:%M:%S %Y %Z"
        )
    except (KeyError, ValueError) as exc:
        return fail(f"cannot determine expiration date: {exc}")

    now = datetime.datetime.utcnow()
    if expires <= now:
        return fail(f"certificate expired on {expires:%Y-%m-%d}")

    if not os.path.isfile(KEY_PATH):
        return fail(f"{KEY_PATH} does not exist")

    try:
        if not key_matches_certificate(CERT_PATH, KEY_PATH):
            return fail("private key does not match the certificate")
    except RuntimeError as exc:
        return fail(str(exc))

    if not os.path.isfile(PEM_PATH):
        return fail(f"{PEM_PATH} does not exist")
    with open(PEM_PATH, "r", encoding="utf-8") as handle:
        combined = handle.read()
    if "BEGIN PRIVATE KEY" not in combined or "BEGIN CERTIFICATE" not in combined:
        return fail(f"{PEM_PATH} does not contain both the key and certificate")

    fingerprint = hashlib.sha256(der_data).hexdigest().upper()
    fingerprint = ":".join(
        fingerprint[i:i + 2] for i in range(0, len(fingerprint), 2)
    )

    print(f"Certificate file: {CERT_PATH}")
    print(f"Common Name: {common_name}")
    print(f"Expiration date: {expires:%Y-%m-%d}")
    print(f"SHA-256 fingerprint: {fingerprint}")
    print("Certificate verification successful")
    return 0


if __name__ == "__main__":
    sys.exit(main())
