    """Extract the commonName value from a decoded certificate subject."""
    for rdn in decoded.get("subject", ()):
        # Depending on the Python version an RDN is either a (key, value)
        # pair or a tuple containing one or more such pairs.
        if len(rdn) == 2 and isinstance(rdn[0], str):
            pairs = (rdn,)
        else:
            pairs = rdn
        for key, value in pairs:
            if key == "commonName":
                return value
    return None


